olMadDiffs,\n    colMads, colMaxs, colMeans2, colMedians, colMins, colOrderStats,\n    colProds, colQuantiles, colRanges, colRanks, colSdDiffs, colSds,\n    colSums2, colTabulates, colVarDiffs, colVars, colWeightedMads,\n    colWeightedMeans, colWeightedMedians, colWeightedSds,\n    colWeightedVars, rowAlls, rowAnyNAs, rowAnys, rowAvgsPerColSet,\n    rowCollapse, rowCounts, rowCummaxs, rowCummins, rowCumprods,\n    rowCumsums, rowDiffs, rowIQRDiffs, rowIQRs, rowLogSumExps,\n    rowMadDiffs, rowMads, rowMaxs, rowMeans2, rowMedians, rowMins,\n    rowOrderStats, rowProds, rowQuantiles, rowRanges, rowRanks,\n    rowSdDiffs, rowSds, rowSums2, rowTabulates, rowVarDiffs, rowVars,\n    rowWeightedMads, rowWeightedMeans, rowWeightedMedians,\n    rowWeightedSds, rowWeightedVars\n\n\nLoading required package: Biobase\n\nWelcome to Bioconductor\n\n    Vignettes contain introductory material; view with\n    'browseVignettes()'. To cite Bioconductor, see\n    'citation(\"Biobase\")', and for packages 'citation(\"pkgname\")'.\n\n\n\nAttaching package: ‘Biobase’\n\n\nThe following object is masked from ‘package:MatrixGenerics’:\n\n    rowMedians\n\n\nThe following objects are masked from ‘package:matrixStats’:\n\n    anyMissing, rowMedians\n\n\nThe following object is masked from ‘package:httr’:\n\n    content\n\n\n","output_type":"stream"}],"execution_count":1},{"cell_type":"code","source":"# --- 1. DOWNLOAD TCGA-BRCA (Breast Invasive Carcinoma) ---\nquery_brca <- GDCquery(\n  project = \"TCGA-BRCA\",\n  data.category = \"Transcriptome Profiling\",\n  data.type = \"Gene Expression Quantification\",\n  workflow.type = \"STAR - Counts\"\n)\n# Download using API in chunks to ensure stability\nGDCdownload(query_brca, method = \"api\", files.per.chunk = 20)\nbrca_data <- GDCprepare(query_brca)\n\n# --- 2. DOWNLOAD TCGA-LUAD (Lung Adenocarcinoma) ---\nquery_luad <- GDCquery(\n  project = \"TCGA-LUAD\",\n  data.category = \"Transcriptome Profiling\",\n  data.type = \"Gene Expression Quantification\",\n  workflow.type = \"STAR - Counts\"\n)\nGDCdownload(query_luad, method = \"api\", files.per.chunk = 20)\nluad_data <- GDCprepare(query_luad)\n","metadata":{"trusted":true,"execution":{"iopub.status.busy":"2026-08-15T14:56:20.844072Z","iopub.execute_input":"2026-08-15T14:56:20.869675Z"}},"outputs":[{"name":"stderr","text":"--------------------------------------\n\no GDCquery: Searching in GDC database\n\n--------------------------------------\n\nGenome of reference: hg38\n\n--------------------------------------------\n\noo Accessing GDC. This might take a while...\n\n--------------------------------------------\n\nooo Project: TCGA-BRCA\n\n--------------------\n\noo Filtering results\n\n--------------------\n\nooo By data.type\n\nooo By workflow.type\n\n----------------\n\noo Checking data\n\n----------------\n\nooo Checking if there are duplicated cases\n\nooo Checking if there are results for the query\n\n-------------------\n\no Preparing output\n\n-------------------\n\nDownloading data for project TCGA-BRCA\n\nGDCdownload will download 1231 files. A total of 5.223473855 GB\n\nDownloading chunk 1 of 62 (20 files, size = 84.828764 MB) as Sat_Aug_15_14_57_18_2026_0.tar.gz\n\n","output_type":"stream"},{"name":"stdout","text":"Downloading: 21 MB        ","output_type":"stream"},{"name":"stderr","text":"Downloading chunk 2 of 62 (20 files, size = 84.986265 MB) as Sat_Aug_15_14_57_18_2026_1.tar.gz\n\n","output_type":"stream"},{"name":"stdout","text":"Downloading: 15 MB        ","output_type":"stream"}],"execution_count":null},{"cell_type":"code","source":"# Extract counts and sample metadata from the prepared objects\ncounts_matrix_brca <- assay(brca_data, \"unstranded\")\nsample_info_brca <- as.data.frame(colData(brca_data))\n\n# Build the DESeq Object\ndds_brca <- DESeqDataSetFromMatrix(countData = counts_matrix_brca,\n                                   colData = sample_info_brca,\n                                   design = ~ sample_type)\n\n# PRE-FILTER: Keep only genes with a total count of 10 or more across all samples\nkeep_brca <- rowSums(counts(dds_brca)) >= 10\ndds_brca <- dds_brca[keep_brca, ]\n\n# Run the heavy statistical analysis\ndds_brca <- DESeq(dds_brca)\nres_brca <- results(dds_brca)\n\n# Export the raw results to save your progress\nwrite.csv(as.data.frame(res_brca), \"TCGA_BRCA_Full_DEGs.csv\")\n","metadata":{"trusted":true},"outputs":[],"execution_count":null},{"cell_type":"code","source":"# Example for exporting Volcano Plot\ntiff(\"Figure_1_Volcano_BRCA.tiff\", width = 8, height = 8, units = \"in\", res = 300)\nEnhancedVolcano(res_brca,\n    lab = rownames(res_brca),\n    x = 'log2FoldChange',\n    y = 'pvalue',\n    title = 'TCGA-BRCA Differential Expression')\ndev.off() # Closes and saves the file\n","metadata":{"trusted":true},"outputs":[],"execution_count":null}]}